# 输入: 群 G 的元素列表(每个是 X 上的置换), 以及枚举 X 的方案
# 输出: 轨道数 |X/G|

def burnside(G, count_fixed):
  return sum(count_fixed(g) for g in G) / len(G)

def count_fixed_naive(g, X):
  # 朴素: 遍历所有对象 x 检查 g·x == x
  return sum(1 for x in X if apply(g, x) == x)

